import { monotonicNow } from "./clock";
import { isWrapped, markWrapped } from "./patch-marker";
import type { RequestTraceContext, TraceContextManager } from "./trace-context";
import type { ClientEvent, EventSeverity } from "./types";
import { isUnderBase, parseAbsoluteUrl } from "./url";

/**
 * Everything the network patches need at request time. A binding builds one
 * at init and activates it; the patches themselves install dormant (possibly
 * before init, via a register entrypoint) and consult the active slot per
 * call. Undefined slot = transparent passthrough.
 */
export interface NetworkCaptureOptions {
  emit(event: ClientEvent): void;
  traceContext: TraceContextManager;
  /** Emit network events. */
  capture: boolean;
  /** Inject `traceparent` into allowlisted requests. */
  propagateTraceContext: boolean;
  /** Injection allowlist; empty defers to `isDefaultInjectionTarget`. */
  allowlist: (string | RegExp)[];
  /** Query parameter names redacted from `url.full` beside the default list. */
  redactQueryParams?: (string | RegExp)[];
  /** Response headers probed for a platform request id, in priority order. */
  requestIdHeaders: string[];
  /** SDK-internal endpoints: never captured, never injected. */
  isInternalUrl(url: string): boolean;
  /**
   * Absolute URL for a request target as the host resolves it, with embedded
   * credentials stripped; undefined when the input cannot be parsed.
   */
  resolveUrl(raw: string): string | undefined;
  /** Injection policy when the allowlist is empty (same-origin on the web). */
  isDefaultInjectionTarget(resolved: string): boolean;
  /** Origin elided from the display path in event bodies, if the host has one. */
  displayOrigin?: string;
  /** Host-reported offline state; a failure while offline reads as an abort. */
  isOffline?(): boolean;
}

let active: NetworkCaptureOptions | undefined;

export const activateNetworkCapture = (
  options: NetworkCaptureOptions,
): void => {
  active = options;
};

export const deactivateNetworkCapture = (): void => {
  active = undefined;
};

export const getActiveNetworkCapture = (): NetworkCaptureOptions | undefined =>
  active;

// --------------------------------------------------------------- display --

/** Compact display path: pathname when on the display origin, host+path otherwise. */
export const urlPath = (resolved: string, displayOrigin?: string): string => {
  const url = parseAbsoluteUrl(resolved);
  if (!url) return resolved;
  return displayOrigin !== undefined && url.origin === displayOrigin
    ? url.pathname
    : `${url.host}${url.pathname}`;
};

/** Status 0 means transport failure. */
export const severityForStatus = (status: number): EventSeverity => {
  if (status === 0 || status >= 500) return "ERROR";
  if (status >= 400) return "WARN";
  return "INFO";
};

/**
 * Query and fragment parameters whose values never leave the device: bearer
 * tokens, OAuth codes, API keys, and presigned-URL signatures. Matched by
 * name, case-insensitively; `network.redactQueryParams` adds to the list.
 */
const REDACTED_QUERY_PARAMS = new Set([
  "token",
  "access_token",
  "refresh_token",
  "id_token",
  "api_key",
  "apikey",
  "key",
  "secret",
  "password",
  "signature",
  "sig",
  "x-amz-signature",
  "x-amz-credential",
  "x-goog-signature",
  "sentry_key",
  "authorization",
  "auth",
  "session",
  "sid",
  "code",
]);

/**
 * `RegExp#test` from the start of `value` every time. A global or sticky
 * pattern resumes from the `lastIndex` its previous match left, so an app's
 * `/^tenant$/g` would match one parameter and let the next one through.
 * Reset only for those flags: a frozen plain RegExp stays untouched.
 */
const testPattern = (pattern: RegExp, value: string): boolean => {
  if (pattern.global || pattern.sticky) pattern.lastIndex = 0;
  return pattern.test(value);
};

/**
 * A recorded URL: the value of every sensitive parameter after the path
 * replaced with `[redacted]`, in the query and in the fragment. `?` separates
 * inside the fragment as well, so a hash router's `#/reset?token=…` is
 * covered. Credentials in the authority are already gone (`resolveUrl`
 * strips them). Applied to `url.full` of requests, resource rows and
 * navigations, and to the page URL the browser SDK stamps on every event.
 */
export const redactUrl = (
  url: string,
  extra: (string | RegExp)[] = [],
): string => {
  const start = url.search(/[?#]/);
  if (start === -1) return url;
  const sensitive = (raw: string): boolean => {
    let name = raw;
    try {
      name = decodeURIComponent(raw);
    } catch {
      // Keep the raw name.
    }
    name = name.toLowerCase();
    return (
      REDACTED_QUERY_PARAMS.has(name) ||
      extra.some((pattern) =>
        typeof pattern === "string"
          ? pattern.toLowerCase() === name
          : testPattern(pattern, name),
      )
    );
  };
  return (
    url.slice(0, start) +
    url
      .slice(start)
      .replace(/([?#&])([^=&#?]+)=([^&#]*)/g, (param, separator, name) =>
        sensitive(name) ? `${separator}${name}=[redacted]` : param,
      )
  );
};

// ------------------------------------------------------------- injection --

/**
 * One allowlist entry against a request URL. A RegExp is tested against the
 * full URL; a string with a scheme is an origin (plus an optional path
 * prefix); any other string is a host (`api.example.com`, with a port when it
 * names one) or, with a leading dot, a domain and its subdomains
 * (`.example.com`).
 */
const matchesAllowlistEntry = (
  resolved: string,
  entry: string | RegExp,
): boolean => {
  if (typeof entry !== "string") return testPattern(entry, resolved);
  if (entry.includes("://")) {
    return isUnderBase({ url: resolved, base: entry });
  }
  const url = parseAbsoluteUrl(resolved);
  if (!url) return false;
  const host = entry.toLowerCase();
  if (host.startsWith(".")) {
    return url.hostname === host.slice(1) || url.hostname.endsWith(host);
  }
  return (host.includes(":") ? url.host : url.hostname) === host;
};

export const isAllowedForInjection = (
  options: NetworkCaptureOptions,
  resolved: string,
): boolean => {
  if (options.allowlist.length === 0) {
    try {
      return options.isDefaultInjectionTarget(resolved);
    } catch {
      return false;
    }
  }
  return options.allowlist.some((entry) =>
    matchesAllowlistEntry(resolved, entry),
  );
};

/** Injection eligibility for the active config; used by the browser's resource
 * observer to decide whether a bypassed request is a diagnosable gap. */
export const isActiveInjectionTarget = (resolved: string): boolean => {
  const options = active;
  if (!options?.propagateTraceContext) return false;
  if (options.isInternalUrl(resolved)) return false;
  return isAllowedForInjection(options, resolved);
};

// ----------------------------------------------------- wrapper-seen ledger --
// Every request processed by an active wrapper is recorded so a passive
// observer (resource timing in the browser) can tell wrapper-captured traffic
// from traffic that bypassed the patches entirely.

interface SeenRequest {
  url: string;
  /** monotonicNow() timebase, comparable to PerformanceEntry.startTime. */
  startTime: number;
}

const SEEN_MATCH_WINDOW_MS = 5_000;
const SEEN_MAX_ENTRIES = 300;
let seenByWrapper: SeenRequest[] = [];

export const recordWrapperRequest = (url: string): void => {
  seenByWrapper.push({ url, startTime: monotonicNow() });
  if (seenByWrapper.length > SEEN_MAX_ENTRIES) {
    seenByWrapper = seenByWrapper.slice(-SEEN_MAX_ENTRIES);
  }
};

/** Consume a wrapper-seen record matching this request, if any. */
export const consumeWrapperSeen = (url: string, startTime: number): boolean => {
  const index = seenByWrapper.findIndex(
    (seen) =>
      seen.url === url &&
      Math.abs(seen.startTime - startTime) <= SEEN_MATCH_WINDOW_MS,
  );
  if (index === -1) return false;
  seenByWrapper.splice(index, 1);
  return true;
};

export const resetWrapperLedger = (): void => {
  seenByWrapper = [];
};

// ---------------------------------------------------------------- events --

export interface NetworkEventDetails {
  kind: "fetch" | "xhr";
  method: string;
  resolvedUrl: string;
  status: number;
  durationMs: number;
  severity?: EventSeverity;
  failureMessage?: string;
  injected?: RequestTraceContext;
  requestId?: string;
  requestIdHeader?: string;
}

export const emitNetworkEvent = (
  options: NetworkCaptureOptions,
  details: NetworkEventDetails,
): void => {
  try {
    const path = urlPath(details.resolvedUrl, options.displayOrigin);
    const outcome = details.status > 0 ? String(details.status) : "failed";
    const event: ClientEvent = {
      type: "network",
      body: `${details.method} ${path} → ${outcome}`,
      severity: details.severity ?? severityForStatus(details.status),
      timeUnixMs: Date.now(),
      attributes: {
        "http.request.method": details.method,
        "http.response.status_code":
          details.status > 0 ? details.status : undefined,
        "url.full": redactUrl(details.resolvedUrl, options.redactQueryParams),
        "app.network.kind": details.kind,
        "app.network.duration_ms": Math.round(details.durationMs),
        "app.network.error": details.failureMessage,
        "app.network.request_id": details.requestId,
        "app.network.request_id_header": details.requestIdHeader,
      },
    };
    if (details.injected) {
      event.traceId = details.injected.traceId;
      event.spanId = details.injected.spanId;
    }
    options.emit(event);
  } catch {
    // Capture failures must never surface to the host.
  }
};

export const readRequestId = (
  options: NetworkCaptureOptions,
  getHeader: (name: string) => string | null | undefined,
): { requestId?: string; requestIdHeader?: string } => {
  try {
    for (const name of options.requestIdHeaders) {
      const value = getHeader(name);
      if (value) return { requestId: value, requestIdHeader: name };
    }
  } catch {}
  return {};
};

export const isAborted = (
  error: unknown,
  signalAborted?: boolean,
  offline?: boolean,
): boolean => {
  if (signalAborted || offline) {
    return true;
  }
  const e = error as { name?: string; message?: string } | undefined;
  return (
    e?.name === "AbortError" ||
    (typeof e?.message === "string" && /abort|cancel/i.test(e.message))
  );
};

// ------------------------------------------------------------------ XHR --
// The one network patch every host shares: browsers have XMLHttpRequest
// natively, and React Native's fetch is a polyfill over its own
// XMLHttpRequest class, so this patch alone sees every mobile request.

interface XhrRequestState {
  method: string;
  resolvedUrl?: string;
  customTraceparent: boolean;
  injected?: RequestTraceContext;
  start: number;
  /** Set by the outermost of our send wrappers in a third-party sandwich. */
  processed: boolean;
  aborted?: boolean;
  /** The capture instance that sent the request; only it may emit the row. */
  owner?: NetworkCaptureOptions;
}

/**
 * The XMLHttpRequest surface the patch touches, declared structurally so the
 * same source typechecks against the DOM lib (browser SDK) and against no
 * lib at all (this package).
 */
interface XhrLike {
  open(...args: unknown[]): void;
  send(body?: unknown): void;
  setRequestHeader(name: string, value: string): void;
  getResponseHeader(name: string): string | null;
  addEventListener(type: string, listener: () => void): void;
  readonly status: number;
  readonly readyState: number;
}

const XHR_DONE = 4;

const xhrState = new WeakMap<XhrLike, XhrRequestState>();

interface XhrOutcome {
  status: number;
  end: number;
  requestId: { requestId?: string; requestIdHeader?: string };
}

const outcomeOf = (xhr: XhrLike, owner: NetworkCaptureOptions): XhrOutcome => ({
  status: xhr.status,
  end: monotonicNow(),
  requestId: readRequestId(owner, (name) => xhr.getResponseHeader(name)),
});

/**
 * One `abort`/`loadend` listener pair per XHR object, reading the request the
 * object is carrying now. An object reused for a second request (open, send,
 * open, send) gets no second pair, so a finished request's listener never
 * emits again with its stale state.
 */
interface XhrListenerSlot {
  current?: XhrRequestState;
  /**
   * A finished request whose `loadend` had not reached our listener when the
   * app opened the next request on the object: an app listener added before
   * ours may start that request from inside the event. Its outcome is read
   * before `open()` resets the status and response headers.
   */
  finished?: { tracked: XhrRequestState; outcome: XhrOutcome };
}

const xhrListeners = new WeakMap<XhrLike, XhrListenerSlot>();

const emitXhr = (
  tracked: XhrRequestState | undefined,
  outcome: (owner: NetworkCaptureOptions) => XhrOutcome,
): void => {
  const owner = tracked?.owner;
  // A request belongs to the instance that sent it: one that completes
  // after shutdown(), or after a later init(), emits nowhere.
  if (!tracked || !owner || owner !== active) {
    return;
  }
  try {
    const { status, end, requestId } = outcome(owner);
    const aborted =
      status === 0 &&
      (tracked.aborted || isAborted(undefined, false, owner.isOffline?.()));
    emitNetworkEvent(owner, {
      kind: "xhr",
      method: tracked.method,
      resolvedUrl: tracked.resolvedUrl as string,
      status,
      durationMs: end - tracked.start,
      severity: aborted ? "DEBUG" : undefined,
      injected: tracked.injected,
      ...requestId,
    });
  } catch {
    // Capture failures must never surface to the host.
  }
};

const listenTo = (xhr: XhrLike): XhrListenerSlot => {
  const existing = xhrListeners.get(xhr);
  if (existing) {
    return existing;
  }
  const slot: XhrListenerSlot = {};
  xhr.addEventListener("abort", () => {
    if (slot.current) {
      slot.current.aborted = true;
    }
  });
  xhr.addEventListener("loadend", () => {
    const finished = slot.finished;
    slot.finished = undefined;
    if (finished) {
      emitXhr(finished.tracked, () => finished.outcome);
      // The request in `current` was opened during this event and its own
      // `loadend` is still to come.
      if (xhr.readyState !== XHR_DONE) {
        return;
      }
    }
    const tracked = slot.current;
    slot.current = undefined;
    emitXhr(tracked, (owner) => outcomeOf(xhr, owner));
  });
  xhrListeners.set(xhr, slot);
  return slot;
};

interface XhrPatch {
  originalOpen: XhrLike["open"];
  originalSend: XhrLike["send"];
  originalSetRequestHeader: XhrLike["setRequestHeader"];
  wrappedOpen: XhrLike["open"];
  wrappedSend: XhrLike["send"];
  wrappedSetRequestHeader: XhrLike["setRequestHeader"];
}

let xhrPatch: XhrPatch | undefined;

const makeXhrPatch = (proto: XhrLike): XhrPatch => {
  const originalOpen = proto.open;
  const originalSend = proto.send;
  const originalSetRequestHeader = proto.setRequestHeader;

  // Forward `open` arguments with exact arity: `open(m, u, undefined)` would
  // coerce async to false (sync XHR), which is not equivalent to the 2-arg call.
  const wrappedOpen = function (this: XhrLike, ...args: unknown[]): void {
    const options = active;
    if (options) {
      try {
        const [method, url] = args;
        xhrState.set(this, {
          method: String(method).toUpperCase(),
          resolvedUrl: options.resolveUrl(String(url)),
          customTraceparent: false,
          start: 0,
          processed: false,
        });
      } catch {
        // Tracking failure must not affect the request.
      }
    }
    try {
      // A tracked request on a finished object is inside its completion
      // events, before our `loadend` listener ran: keep its outcome.
      const slot = xhrListeners.get(this);
      const tracked = slot?.current;
      if (slot && tracked?.owner && this.readyState === XHR_DONE) {
        slot.finished = { tracked, outcome: outcomeOf(this, tracked.owner) };
        slot.current = undefined;
      }
    } catch {
      // Tracking failure must not affect the request.
    }
    originalOpen.apply(this, args);
  };

  const wrappedSetRequestHeader = function (
    this: XhrLike,
    name: string,
    value: string,
  ): void {
    if (active) {
      try {
        if (name.toLowerCase() === "traceparent") {
          const tracked = xhrState.get(this);
          if (tracked) {
            tracked.customTraceparent = true;
          }
        }
      } catch {
        // Ignore.
      }
    }
    originalSetRequestHeader.call(this, name, value);
  };

  const wrappedSend = function (this: XhrLike, body?: unknown): void {
    const options = active;
    if (options) {
      try {
        const tracked = xhrState.get(this);
        // `processed` = an outer copy of our wrapper already handled this
        // send (third-party sandwich); inner copies must not re-inject or
        // attach a second loadend emitter.
        if (tracked?.resolvedUrl && !tracked.processed) {
          tracked.processed = true;
          const internal = options.isInternalUrl(tracked.resolvedUrl);

          if (
            !internal &&
            options.propagateTraceContext &&
            !tracked.customTraceparent &&
            isAllowedForInjection(options, tracked.resolvedUrl)
          ) {
            try {
              const requestContext = options.traceContext.forRequest();
              for (const [name, value] of Object.entries(
                requestContext.headers,
              )) {
                originalSetRequestHeader.call(this, name, value);
              }
              tracked.injected = requestContext;
            } catch {
              tracked.injected = undefined;
            }
          }

          if (!internal) {
            recordWrapperRequest(tracked.resolvedUrl);
          }

          if (!internal && options.capture) {
            tracked.start = monotonicNow();
            tracked.owner = options;
            listenTo(this).current = tracked;
          }
        }
      } catch {
        // Fall through to the untouched send.
      }
    }
    originalSend.call(this, body);
  };

  return {
    originalOpen,
    originalSend,
    originalSetRequestHeader,
    wrappedOpen,
    wrappedSend,
    wrappedSetRequestHeader,
  };
};

const xhrPrototype = (): XhrLike | undefined => {
  const ctor = (globalThis as { XMLHttpRequest?: { prototype: XhrLike } })
    .XMLHttpRequest;
  return ctor?.prototype;
};

/**
 * Install the dormant XMLHttpRequest patch around whatever implementation is
 * currently live. Idempotent, and re-wraps when a later actor replaced the
 * prototype methods after an earlier install (the displaced wrapper is an
 * inert passthrough, so single-processing holds).
 */
export const ensureXhrPatch = (): void => {
  const proto = xhrPrototype();
  if (!proto || isWrapped(proto.open)) {
    return;
  }
  const patch = makeXhrPatch(proto);
  markWrapped(patch.wrappedOpen);
  markWrapped(patch.wrappedSetRequestHeader);
  markWrapped(patch.wrappedSend);
  try {
    proto.open = patch.wrappedOpen;
    proto.setRequestHeader = patch.wrappedSetRequestHeader;
    proto.send = patch.wrappedSend;
  } catch {
    // A frozen prototype stays native: put back whatever was assigned
    // before the refusal, capture no requests, and let init() carry on.
    try {
      proto.open = patch.originalOpen;
      proto.setRequestHeader = patch.originalSetRequestHeader;
      proto.send = patch.originalSend;
    } catch {
      // Nothing was assigned.
    }
    return;
  }
  xhrPatch = patch;
};

/**
 * Restore the natives if the current implementations are still ours; if
 * someone patched on top of us, restoring would clobber them, and the
 * inactive wrappers pass through.
 */
export const uninstallXhrPatch = (): void => {
  const proto = xhrPrototype();
  if (proto && xhrPatch) {
    if (proto.open === xhrPatch.wrappedOpen) {
      proto.open = xhrPatch.originalOpen;
    }
    if (proto.setRequestHeader === xhrPatch.wrappedSetRequestHeader) {
      proto.setRequestHeader = xhrPatch.originalSetRequestHeader;
    }
    if (proto.send === xhrPatch.wrappedSend) {
      proto.send = xhrPatch.originalSend;
    }
  }
  xhrPatch = undefined;
};
