import {
  type EventAttributes,
  parseAbsoluteUrl,
} from "@sazabi/client-sdk-core";
import { NativeModules, Platform, TurboModuleRegistry } from "react-native";

/**
 * react-native-web renders in a real browser, where `@sazabi/browser` owns
 * capture. This SDK installs nothing there.
 */
export const isWebHost = (): boolean => Platform.OS === "web";

const stringOrUndefined = (value: unknown): string | undefined =>
  typeof value === "string" && value.length > 0 ? value : undefined;

/**
 * Resource attributes the host can report without a native module: OTEL
 * `os.*` from `Platform`, the `device.*` fields Android's
 * `Platform.constants` carries (`Brand`, `Manufacturer`, `Model`), and on iOS
 * the manufacturer plus `device.type` from `interfaceIdiom` (`phone`, `pad`,
 * `tv`, `carplay`, `mac`, `vision`). iOS reports no model through JavaScript.
 * `os.name` stays `Platform.OS` (`ios`, `android`) on both, so queries match
 * one casing; iPadOS shows as `device.type: "pad"`.
 */
export const hostResourceAttributes = (): EventAttributes => {
  const constants = (Platform.constants ?? {}) as Record<string, unknown>;
  const ios = Platform.OS === "ios";
  return {
    "os.name": Platform.OS,
    "os.version": stringOrUndefined(String(Platform.Version ?? "")),
    "device.manufacturer": ios
      ? "Apple"
      : (stringOrUndefined(constants.Brand) ??
        stringOrUndefined(constants.Manufacturer)),
    "device.model.identifier": stringOrUndefined(constants.Model),
    "device.type": ios
      ? stringOrUndefined(constants.interfaceIdiom)
      : undefined,
  };
};

export const isDevHost = (): boolean =>
  (globalThis as { __DEV__?: unknown }).__DEV__ === true;

/**
 * The Metro (or Expo) development server this bundle was loaded from, as
 * `<origin>/`, read from `SourceCode.scriptURL` the way React Native's own
 * `getDevServer()` does. Only under `__DEV__`, and only for an http(s)
 * bundle URL: a release bundle loads from a file.
 */
export const devServerOrigin = (): string | undefined => {
  if (!isDevHost()) return undefined;
  try {
    type SourceCode = {
      scriptURL?: unknown;
      getConstants?(): { scriptURL?: unknown };
    };
    const module = (TurboModuleRegistry?.get?.("SourceCode") ??
      NativeModules?.SourceCode) as SourceCode | null | undefined;
    const scriptURL = module?.getConstants?.().scriptURL ?? module?.scriptURL;
    const url =
      typeof scriptURL === "string" ? parseAbsoluteUrl(scriptURL) : undefined;
    return url && url.protocol.startsWith("http")
      ? `${url.origin}/`
      : undefined;
  } catch {
    return undefined;
  }
};

/**
 * A request URL as the core expects it: absolute, credentials stripped.
 * Relative references are not requests on a native host, so they resolve to
 * nothing and are neither captured nor injected.
 */
export const resolveUrl = (raw: string): string | undefined =>
  parseAbsoluteUrl(raw)?.href;
